package main

import "fmt"

type User struct {
	Name string
	Age  int
}

// newUser returns a pointer to a LOCAL variable.
// The compiler detects the escape and allocates u on the heap.
func newUser(name string, age int) *User {
	u := User{Name: name, Age: age} // u escapes via the returned pointer
	return &u                       // safe in Go: never a dangling pointer
}

func main() {
	u := newUser("Ada", 36)
	fmt.Printf("%s is %d\n", u.Name, u.Age)
}

