// formatKey is on a hot path, called per request.
func formatKey(userID int, region string) string {
	// fmt.Sprintf takes ...interface{}: userID is boxed into an
	// interface (an allocation) and a fresh heap string is built
	// on EVERY call. In a hot loop this dominates GC pressure.
	return fmt.Sprintf("u:%d:%s", userID, region)
}

solution.code:
import (
	"strconv"
	"strings"
)

// No interface boxing: strconv.Itoa avoids ...interface{}, and the
// Builder grows a single backing array. One allocation for the result
// instead of several, and no per-arg heap boxing.
func formatKey(userID int, region string) string {
	var b strings.Builder
	b.Grow(len(region) + 16) // preallocate to avoid regrowth
	b.WriteString("u:")
	b.WriteString(strconv.Itoa(userID))
	b.WriteByte(':')
	b.WriteString(region)
	return b.String()
}

func Concat(parts []string) string {
	n := 0
	for _, p := range parts {
		n += len(p)
	}
	var b strings.Builder
	b.Grow(n) // single allocation sized to the final length
	for _, p := range parts {
		b.WriteString(p)
	}
	return b.String() // returned by value, not by pointer
}
